# openEMS plane-cavity resonance sweep (auto-generated by FluxPCB)
# Wideband S21 between two probe ports on the plane pair; resonance dips
# in |S21| are the cavity modes. Run: python resonance_sweep.py
import openems
unit = 1e-3
FDTD = openems.OpenEMS(unit=unit, end_criteria=4000)
FDTD.SetGaussPulse(8e9, f0=4e9)
csx = FDTD.csx
L, W, h = 52.0, 30.0, 1.6
sub = csx.AddMaterial(" sub", epsilon=4.4)
sub.AddBox(xs=0, ys=0, zs=0, xe=L, ye=W, ze=h)
p1 = csx.AddMetal(" p1"); p1.AddBox(xs=0, ys=0, zs=0, xe=L, ye=W, ze=0)
p2 = csx.AddMetal(" p2"); p2.AddBox(xs=0, ys=0, zs=h, xe=L, ye=W, ze=h)
# two lumped ports through the dielectric at opposite corners
for name, (x, y) in (("P1", (2, 2)), ("P2", (L-2, W-2))):
    port = openems.Port(csx, name=name, p_type=0, exc=(1 if name == "P1" else 0))
FDTD.Run("sim_res", verbose=1)
print("modes: minima of |S21| in sim_res port_..._.s2p")
